function _wxRandomString(length = 32) {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    const bytes = crypto.randomBytes(length);
    let result = '';
    for (let i = 0; i < length; i++) {
        result += chars.charAt(bytes[i] % chars.length);
    }
    return result;
}
/** 商户私钥归一化：支持原始 PEM / base64 编码 PEM / 字面量 \n 三种形态 */
function _normalizeWxPrivateKey(key) {
    const trimmed = String(key || '').trim();
    if (!trimmed) {
        return '';
    }
    if (trimmed.includes('-----BEGIN')) {
        return trimmed.replace(/\\n/g, '\n');
    }
    try {
        const decoded = Buffer.from(trimmed, 'base64').toString('utf8');
        if (decoded.includes('-----BEGIN')) {
            return decoded;
        }
    }
    catch (_) { /* fallthrough */ }
    return trimmed.replace(/\\n/g, '\n');
}
function _wxRsaSign(privateKey, data) {
    const sign = crypto.createSign('RSA-SHA256');
    sign.update(data);
    sign.end();
    return sign.sign(_normalizeWxPrivateKey(privateKey), 'base64');
}
function _wxGenerateAuthorization(method, path, body) {
    const timestamp = String(Math.floor(Date.now() / 1000));
    const nonceStr = _wxRandomString(32);
    const message = `${[method, path, timestamp, nonceStr, body].join('\n')}\n`;
    const signature = _wxRsaSign(WECHAT_PAY.privateKey, message);
    return `WECHATPAY2-SHA256-RSA2048 mchid="${WECHAT_PAY.mchId}",nonce_str="${nonceStr}",timestamp="${timestamp}",serial_no="${WECHAT_PAY.serialNo}",signature="${signature}"`;
}
/** 微信支付 V3 JSON 请求（5s 超时，非 2xx 抛错） */
function _wxPayV3Request(method, path, bodyObj) {
    return new Promise((resolve, reject) => {
        const bodyStr = method === 'GET' ? '' : JSON.stringify(bodyObj || {});
        const authorization = _wxGenerateAuthorization(method, path, bodyStr);
        const urlObj = new URL(`${ENDPOINTS.WECHAT_PAY_API_BASE}${path}`);
        const headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'Authorization': authorization,
            'User-Agent': 'WeChat-Mini-Program-Pay',
        };
        if (method === 'POST') {
            headers['Content-Length'] = Buffer.byteLength(bodyStr);
        }
        const req = https.request({
            hostname: urlObj.hostname,
            port: 443,
            path: urlObj.pathname + urlObj.search,
            method,
            headers,
            timeout: 5000,
        }, (res) => {
            let chunks = '';
            res.on('data', (chunk) => { chunks += chunk ? chunk.toString() : ''; });
            res.on('end', () => {
                try {
                    const json = JSON.parse(chunks || '{}');
                    const status = res.statusCode || 0;
                    if (status >= 200 && status < 300) {
                        resolve(json);
                    }
                    else {
                        reject(new Error(`微信支付V3 HTTP ${status}: ${json.message || chunks}`));
                    }
                }
                catch (e) {
                    reject(new Error(`微信支付V3响应解析失败：${chunks}`));
                }
            });
        });
        req.on('error', reject);
        req.on('timeout', () => { req.destroy(); reject(new Error('微信支付V3请求超时')); });
        if (method === 'POST') {
            req.write(bodyStr);
        }
        req.end();
    });
}
// =====================================================================
// 辅助函数：支付参数创建（微信支付 V3 JSAPI 下单）
// =====================================================================
async function _createPaymentParams(openid, orderId, outTradeNo, amount, description) {
    const config = WECHAT_PAY;
    if (!config.appId || !config.mchId || !config.serialNo || !config.privateKey) {
        throw new Error('微信支付V3未配置（需 WECHAT_APPID / WECHAT_MCHID / WECHAT_SERIAL_NO / WECHAT_PRIVATE_KEY）');
    }
    const cloudEnv = cloud.env;
    // notify_url 配置化；未配置时回退到当前云环境回调地址（应指向 paymentService 的 paymentNotify HTTP 触发地址）
    const notifyUrl = config.notifyUrl || `https://${cloudEnv}.ap-shanghai.tencentscf.com/payment/notify`;
    // time_expire 需为北京时间（+08:00）：UTC 时刻先 +8h 再打 +08:00 标签，保证过期时刻正确
    const timeExpire = new Date(Date.now() + 30 * 60 * 1000 + 8 * 3600 * 1000)
        .toISOString().replace(/\.\d{3}Z$/, '+08:00');
    const requestBody = {
        appid: config.appId,
        mchid: config.mchId,
        description,
        out_trade_no: outTradeNo,
        time_expire: timeExpire,
        notify_url: notifyUrl,
        attach: JSON.stringify({ type: 'activity', orderId }),
        amount: { total: Math.round(amount * 100), currency: 'CNY' },
        payer: { openid },
    };
    try {
        const result = await _wxPayV3Request('POST', ENDPOINTS.WECHAT_PAY_JSAPI, requestBody);
        const prepayId = result.prepay_id;
        if (!prepayId) {
            logger.error('_createPaymentParams.v3.noPrepayId', { outTradeNo, result });
            throw new Error(`微信支付V3下单失败：${result.message || '未返回 prepay_id'}`);
        }
        // 小程序调起支付签名：appId\ntimeStamp\nnonceStr\npackage\n（RSA-SHA256）
        const timeStamp = String(Math.floor(Date.now() / 1000));
        const nonceStr = _wxRandomString(32);
        const packageStr = `prepay_id=${prepayId}`;
        const paySign = _wxRsaSign(config.privateKey, `${[config.appId, timeStamp, nonceStr, packageStr].join('\n')}\n`);
        return { timeStamp, nonceStr, package: packageStr, signType: 'RSA', paySign };
    }
    catch (e) {
        logger.error('创建支付参数失败:', e);
        throw new Error(`创建支付参数失败: ${e.message}`);
    }
}
// =====================================================================
// 辅助函数：微信支付 V3 查单（H2 修复：confirm 前核实真实支付状态）
// =====================================================================
async function _queryWechatOrder(outTradeNo) {
    try {
        const config = WECHAT_PAY;
        if (!config.mchId || !config.privateKey) {
            return { paid: false, tradeState: 'NOT_CONFIGURED' };
        }
        const path = `/v3/pay/transactions/out-trade-no/${encodeURIComponent(outTradeNo)}?mchid=${config.mchId}`;
        const result = await _wxPayV3Request('GET', path);
        const tradeState = result.trade_state;
        const amountInfo = (result.amount || {});
        return {
            paid: tradeState === 'SUCCESS',
            totalFee: typeof amountInfo.total === 'number' ? amountInfo.total : undefined,
            tradeState,
            transactionId: result.transaction_id,
        };
    }
    catch (e) {
        logger.error('_queryWechatOrder.failed', { outTradeNo, msg: e.message });
        return { paid: false, tradeState: 'QUERY_FAILED' };
    }
}
// =====================================================================
// Handler 1: getActivityList - 活动列表
// =====================================================================
const ACTIVITY_LIST_FIELDS = {
    _id: true, title: true, coverUrl: true, startTime: true, endTime: true,
    location: true, latitude: true, longitude: true, category: true,
    price: true, pricePerPerson: true, pricePerPet: true,
    maxParticipants: true, currentParticipants: true, status: true, createdBy: true, createdAt: true, organizer: true,
};
const REGISTRATION_LIST_FIELDS = {
    _id: true, activityId: true, openid: true, phone: true, status: true,
    totalAmount: true, createdAt: true,
};
async function getActivityList(event, context, auth) {
    const { page = 1, pageSize = 10, status, category } = event;
    const safePageSize = Math.min(Math.max(1, Number(pageSize) || 10), 100);
    logger.info('getActivityList.query', { page, pageSize: safePageSize, status, category });
    // M4 修复：状态自动更新迁移至定时触发器（见 main 入口 Timer 分支），列表接口只读
    const where = {};
    if (status && status !== 'all') {
        where.status = status;
    }
    else {
        where.status = _.neq('deleted');
    }
    if (category && category !== 'all') {
        where.category = category;
    }
    const result = await paginate(db, 'activities', {
        page, pageSize: safePageSize, where,
        projection: ACTIVITY_LIST_FIELDS,
        orderBy: { field: 'createdAt', direction: 'desc' },
    });
    result.list.forEach((activity) => {
        const avatar = activity.organizer && activity.organizer.avatar;
        if (avatar && !avatar.startsWith('cloud://') && !avatar.startsWith('https://')) {
            if (activity.organizer) {
                activity.organizer.avatar = '';
                activity.organizer._avatarInvalid = true;
            }
        }
    });
    const invalidAvatarActivities = result.list.filter(a => a.organizer && a.organizer._avatarInvalid && a.createdBy);
    if (invalidAvatarActivities.length > 0) {
        const creatorOpenids = [...new Set(invalidAvatarActivities.map(a => a.createdBy).filter((id) => Boolean(id)))];
        try {
            const adminRes = await db.collection('admins').where({ _id: _.in(creatorOpenids) }).field({ avatarUrl: true, nickName: true }).get();
            const adminMap = {};
            (adminRes.data || []).forEach((a) => { if (a._id) {
                adminMap[a._id] = a;
            } });
            invalidAvatarActivities.forEach((activity) => {
                if (!activity.createdBy || !activity.organizer) {
                    return;
                }
                const admin = adminMap[activity.createdBy];
                if (admin && admin.avatarUrl && (admin.avatarUrl.startsWith('cloud://') || admin.avatarUrl.startsWith('https://'))) {
                    activity.organizer.avatar = admin.avatarUrl;
                    if (admin.nickName && activity.organizer.name === '宠团团') {
                        activity.organizer.name = admin.nickName;
                    }
                }
                delete activity.organizer._avatarInvalid;
            });
        }
        catch (e) {
            invalidAvatarActivities.forEach((a) => { if (a.organizer) {
                delete a.organizer._avatarInvalid;
            } });
        }
    }
    logger.info('getActivityList.result', { total: result.total, listCount: result.list.length });
    let myRegistrations = [];
    if (auth.openid) {
        const regRes = await db.collection('activity_registrations')
            .where({ ownerId: auth.openid, status: 'confirmed' })
            .field({ activityId: true })
            .get();
        myRegistrations = (regRes.data || []).map((r) => r.activityId).filter((id) => Boolean(id));
    }
    result.list = result.list.map((activity) => ({
        ...activity,
        joined: myRegistrations.includes(activity._id || ''),
    }));
    return handleSuccess(result, '获取成功');
}
exports.getActivityList = getActivityList;
// =====================================================================
// Handler 2: getActivityDetail - 活动详情
// =====================================================================
async function getActivityDetail(event, context, auth) {
    const { activityId } = event;
    if (!activityId) {
        throw err('INVALID_PARAMS', '缺少活动ID');
    }
    try {
        // L8 修复：主查询与"我是否报名"相互独立，并行执行降低详情接口 P95
        const [res, regRes] = await Promise.all([
            db.collection('activities').doc(activityId).get(),
            auth.openid
                ? db.collection('activity_registrations')
                    .where({ activityId, ownerId: auth.openid, status: 'confirmed' })
                    .count()
                : Promise.resolve({ total: 0 }),
        ]);
        const isRegistered = regRes.total > 0;
        const data = res.data;
        if (!data) {
            throw err('NOT_FOUND', '活动不存在');
        }
        const result = { ...data, isRegistered };
        // L8 修复：头像补全与活动数彼此独立且都依赖主查询结果 → 并行执行
        await Promise.all([
            (async () => {
                if (!(result.organizer && result.organizer.avatar))
                    return;
                const avatar = result.organizer.avatar;
                if (avatar.startsWith('cloud://') || avatar.startsWith('https://'))
                    return;
                result.organizer.avatar = '';
                if (!result.createdBy)
                    return;
                try {
                    const adminRes = await db.collection('admins').doc(result.createdBy).field({ avatarUrl: true, nickName: true }).get();
                    const admin = adminRes.data;
                    if (admin && admin.avatarUrl && (admin.avatarUrl.startsWith('cloud://') || admin.avatarUrl.startsWith('https://'))) {
                        result.organizer.avatar = admin.avatarUrl;
                        if (admin.nickName && result.organizer.name === '宠团团') {
                            result.organizer.name = admin.nickName;
                        }
                    }
                }
                catch (e) {
                    logger.warn('getActivityDetail.admins.fetch', { createdBy: result.createdBy, code: e.errCode, msg: e.message });
                }
            })(),
            (async () => {
                if (!(data.createdBy && result.organizer))
                    return;
                try {
                    const countRes = await db.collection('activities')
                        .where({ createdBy: data.createdBy, status: _.in(['published', 'ongoing', 'ended']) })
                        .count();
                    result.organizer.activityCount = countRes.total || 0;
                }
                catch (e) {
                    logger.warn('queryHostActivities', e);
                    result.organizer.activityCount = 0;
                }
            })(),
        ]);
        return handleSuccess(result, '获取成功');
    }
    catch (error) {
        return handleError(error, '活动不存在', ERROR_CODES.NOT_FOUND);
    }
}
exports.getActivityDetail = getActivityDetail;
// =====================================================================
// Handler 3: createActivity - 创建活动
// =====================================================================
async function createActivity(event, context, auth) {
    const { openid } = auth;
    if (!openid) {
        throw err('AUTH_REQUIRED', '未登录');
    }
    const { title, description, coverUrl, startTime, endTime, location, latitude, longitude, maxParticipants, category, price } = event;
    if (!title) {
        throw err('INVALID_PARAMS', '缺少活动标题');
    }
    // M7 修复：status 枚举白名单（仅 draft/published），杜绝直接创建任意状态
    const requestedStatus = String(event.status || 'draft');
    if (!ACTIVITY_CREATE_STATUS.includes(requestedStatus)) {
        throw err('INVALID_PARAMS', `无效的活动状态: ${requestedStatus}`);
    }
    // M7 修复：直接创建 published 活动时要求关键信息完整
    if (requestedStatus === 'published') {
        if (!startTime || !endTime || !location) {
            throw err('INVALID_PARAMS', '发布活动必须填写开始时间、结束时间和地点');
        }
    }
    // M7 修复：时间格式/先后关系、价格、名额校验
    validateActivityFields({ startTime, endTime, price, pricePerPerson: event.pricePerPerson, pricePerPet: event.pricePerPet, maxParticipants });
    let organizer = null;
    try {
        const userRes = await db.collection('users').doc(openid).get();
        organizer = userRes.data;
    }
    catch (e) {
        logger.warn('createActivity.users.fetch', { openid: maskOpenid(openid), msg: e.message });
    }
    const activity = {
        title,
        description: description || '',
        coverUrl: coverUrl || '',
        images: event.images || [],
        startTime: startTime || '',
        endTime: endTime || '',
        location: location || '',
        latitude: latitude || null,
        longitude: longitude || null,
        maxParticipants: maxParticipants || 0,
        currentParticipants: 0,
        category: category || 'outdoor',
        price: (Number(event.pricePerPerson) || 0) + (Number(event.pricePerPet) || 0) || Number(price) || 0,
        pricePerPerson: Number(event.pricePerPerson) || 0,
        pricePerPet: Number(event.pricePerPet) || 0,
        contactName: event.contactName || '',
        contactPhone: event.contactPhone || '',
        wechatId: event.wechatId || '',
        status: requestedStatus,
        createdBy: openid,
        organizer: organizer ? {
            name: organizer.nickName || '宠团团',
            avatar: organizer.avatarUrl || '/images/default-avatar.svg',
        } : { name: '宠团团', avatar: '/images/default-avatar.svg' },
        createdAt: db.serverDate(),
        updatedAt: db.serverDate(),
    };
    activity._id = generateId('activity', openid);
    const res = await db.collection('activities').add({ data: activity });
    return handleSuccess({ id: res._id }, '创建成功');
}
exports.createActivity = createActivity;
// =====================================================================
// Handler 4: updateActivity - 更新活动
// =====================================================================
async function updateActivity(event, context, auth) {
    const { activityId } = event;
    const { openid } = auth;
    if (!activityId) {
        throw err('INVALID_PARAMS', '缺少活动ID');
    }
    if (!openid) {
        throw err('AUTH_REQUIRED', '未登录');
    }
    const updateData = { updatedAt: db.serverDate(), ...filterFields(FIELD_WHITELISTS.activity, event) };
    const existRes = await db.collection('activities').doc(activityId).get();
    const existData = existRes.data;
    if (!existData) {
        throw err('NOT_FOUND', '活动不存在');
    }
    if (existData.createdBy !== openid) {
        try {
            await checkPartnerPermission(openid, 'activity');
        }
        catch (e) {
            throw err('PERMISSION_DENIED', '无权修改此活动');
        }
    }
    // M7 修复：status 变更走状态机校验，杜绝任意状态跳转（如 ended 改回 published）
    if (updateData.status !== undefined) {
        const nextStatus = String(updateData.status);
        const currStatus = String(existData.status || 'draft');
        if (nextStatus !== currStatus) {
            const allowed = ACTIVITY_STATUS_TRANSITIONS[currStatus] || [];
            if (!allowed.includes(nextStatus)) {
                throw err('INVALID_PARAMS', `活动状态不允许从 ${currStatus} 变更为 ${nextStatus}`);
            }
        }
        else {
            delete updateData.status;
        }
    }
    // M7 修复：更新时同样校验时间/价格/名额字段合法性
    validateActivityFields({
        startTime: updateData.startTime ?? (event.startTime !== undefined ? event.startTime : undefined),
        endTime: updateData.endTime ?? (event.endTime !== undefined ? event.endTime : undefined),
        price: updateData.price,
        pricePerPerson: updateData.pricePerPerson,
        pricePerPet: updateData.pricePerPet,
        maxParticipants: updateData.maxParticipants,
    });
    // 时间只改其一时，与库中另一端做先后关系校验
    const effStart = updateData.startTime !== undefined ? updateData.startTime : existData.startTime;
    const effEnd = updateData.endTime !== undefined ? updateData.endTime : existData.endTime;
    if (effStart && effEnd) {
        validateActivityFields({ startTime: effStart, endTime: effEnd });
    }
    await db.collection('activities').doc(activityId).update({ data: updateData });
    return handleSuccess(null, '更新成功');
}
exports.updateActivity = updateActivity;
// =====================================================================
// Handler 5: deleteActivity - 删除活动
// =====================================================================
async function deleteActivity(event, context, auth) {
    const { activityId } = event;
    const { openid } = auth;
    if (!activityId) {
        throw err('INVALID_PARAMS', '缺少活动ID');
    }
    if (!openid) {
        throw err('AUTH_REQUIRED', '未登录');
    }
    const existRes = await db.collection('activities').doc(activityId).get();
    const existData = existRes.data;
    if (!existData) {
        throw err('ACTIVITY_NOT_FOUND', '活动不存在');
    }
    if (existData.status === 'published') {
        throw err('INVALID_PARAMS', '已发布的活动不能删除');
    }
    if (existData.createdBy !== openid) {
        try {
            await checkPartnerPermission(openid, 'activity');
        }
        catch (e) {
            throw err('PERMISSION_DENIED', '无权删除此活动');
        }
    }
    const regCountRes = await db.collection('activity_registrations')
        .where({ activityId })
        .count();
    const regCount = regCountRes.total || 0;
    if (regCount > 0) {
        throw err('ACTIVITY_HAS_REGISTRATIONS', `该活动已有 ${regCount} 人报名，无法删除`, { regCount });
    }
    await db.collection('activities').doc(activityId).remove();
    return handleSuccess(null, '删除成功');
}
exports.deleteActivity = deleteActivity;
// =====================================================================
// Handler 6: submitRegistration - 提交报名（含风控前置）
// =====================================================================
async function submitRegistration(event, context, auth) {
    const { openid } = auth;
    if (!openid) {
        throw err('AUTH_REQUIRED', '未登录');
    }
    const { activityId, pets, phone, notes, friends, petIds, totalAmount, originalAmount, couponId, couponDiscount, participantCount } = event;
    if (!activityId) {
        throw err('INVALID_PARAMS', '缺少活动ID');
    }
    if (!pets || !Array.isArray(pets) || pets.length === 0) {
        throw err('INVALID_PARAMS', '请选择参与的宠物');
    }
    if (!phone) {
        throw err('INVALID_PARAMS', '请填写联系电话');
    }
    // M1 修复：查重前置到事务外（CloudBase 事务内不支持 where 查询），
    // 名额检查移入事务内基于快照读，避免"读-判-写"跨事务竞态
    const existReg = await db.collection('activity_registrations')
        .where({ activityId, ownerId: openid, status: 'confirmed' })
        .count();
    if (existReg.total > 0) {
        throw err('BUSINESS_ERROR', '您已报名此活动');
    }
    const transaction = await db.startTransaction();
    try {
        // M1 修复：活动读取走事务快照，与后续 _.inc 同事务；
        // 并发提交冲突时 CloudBase 事务失败回滚，杜绝名额超卖
        const activityRes = await transaction.collection('activities').doc(activityId).get();
        const activity = activityRes.data;
        if (!activity) {
            throw err('NOT_FOUND', '活动不存在');
        }
        const pricePerPerson = activity.pricePerPerson || 0;
        const pricePerPet = activity.pricePerPet || 0;
        // M2 修复：participantCount 服务端规范化（≥1 的整数），不再裸信前端
        const pCount = Math.max(1, Math.floor(Number(participantCount) || 1));
        if (activity.maxParticipants && (activity.currentParticipants || 0) + pCount > activity.maxParticipants) {
            throw err('BUSINESS_ERROR', '报名人数已满');
        }
        const petsArray = pets;
        const friendsArray = Array.isArray(friends) ? friends : [];
        const petCount = petsArray.length + friendsArray.length;
        // H3 修复：金额一律服务端重算，不再信任前端 totalAmount
        const calculatedAmount = computeActivityAmount(activity, pCount, petCount);
        const coupon = await resolveCoupon(openid, couponId, calculatedAmount);
        const finalAmount = Math.max(0, Math.round((calculatedAmount - coupon.discount) * 100) / 100);
        // Sprint 22: 活动报名前先做大额风控
        const applyRisk = await performActivityApplyRiskCheck({
            openid,
            activityId,
            amountFen: Math.round(calculatedAmount * 100),
        });
        const isPaid = calculatedAmount > 0;
        const now = db.serverDate();
        const petsInfo = petsArray.map((p) => ({
            name: p.petName || p.name || '',
            gender: p.petGender || p.gender || 'male',
            breed: p.petBreed || p.breed || '',
            petId: p.petId || '',
        }));
        const registration = {
            _id: generateId('registration', openid),
            activityId,
            ownerId: openid,
            pets: petsInfo,
            petIds: petIds || [],
            phone: phone || '',
            notes: notes || '',
            friends: friendsArray,
            status: isPaid ? 'pending_payment' : 'confirmed',
            participantCount: pCount,
            petCount,
            pricePerPerson,
            pricePerPet,
            totalAmount: calculatedAmount,
            originalAmount: calculatedAmount,
            couponId: coupon.couponId,
            couponDiscount: coupon.discount,
            finalAmount,
            pendingReview: applyRisk.pendingReview,
            riskDecision: applyRisk.decision,
            riskReasons: applyRisk.reasons,
            createdAt: now,
            updatedAt: now,
        };
        const regResult = await transaction.collection('activity_registrations').add({ data: registration });
        if (!isPaid) {
            await transaction.collection('activities').doc(activityId).update({
                data: {
                    currentParticipants: _.inc(pCount),
                    updatedAt: db.serverDate(),
                },
            });
        }
        try {
            let user = null;
            try {
                const userRes = await db.collection('users').doc(openid).get();
                user = userRes.data;
            }
            catch (e) {
                logger.warn('submitRegistration.users.fetch', { openid: maskOpenid(openid), code: e.errCode, msg: e.message });
            }
            const activityOrder = {
                ownerId: openid,
                orderType: 'activity',
                activityId,
                activityTitle: activity.title || '',
                activityCoverUrl: activity.coverUrl || '',
                activityStartTime: activity.startTime || '',
                activityEndTime: activity.endTime || '',
                activityLocation: activity.location || '',
                organizerId: activity.createdBy || '',
                petIds: petIds || [],
                petsInfo,
                startDate: activity.startTime || '',
                endDate: activity.endTime || '',
                duration: 1,
                pricePerDay: activity.price || 0,
                participantCount: pCount,
                petCount,
                pricePerPerson,
                pricePerPet,
                basicPrice: calculatedAmount,
                totalPrice: finalAmount,
                originalAmount: calculatedAmount,
                couponId: coupon.couponId,
                couponDiscount: coupon.discount,
                phone: phone || '',
                notes: notes || '',
                status: isPaid ? 'pending_payment' : 'confirmed',
                ownerInfo: user ? { nickName: user.nickName, avatarUrl: user.avatarUrl, phone } : { phone },
                createdAt: now,
                updatedAt: now,
            };
            await transaction.collection('orders').add({ data: activityOrder });
        }
        catch (orderErr) {
            logger.warn('创建活动订单记录失败:', orderErr.message);
        }
        await transaction.commit();
        return handleSuccess({ id: regResult._id || 'ok', registrationId: regResult._id }, '报名成功');
    }
    catch (error) {
        // M1 修复：rollback 包裹 try/catch，避免二次 rollback 抛新错掩盖原始业务错误
        try {
            await transaction.rollback();
        }
        catch (_) { /* ignore rollback error */ }
        return handleError(error, '报名失败', ERROR_CODES.DATA);
    }
}
exports.submitRegistration = submitRegistration;
// =====================================================================
// Handler 7: getRegistrationDetail - 报名详情
// =====================================================================
async function getRegistrationDetail(event, context, auth) {
    const { openid } = auth;
    if (!openid) {
        throw err('AUTH_REQUIRED', '未登录');
    }
    const { registrationId } = event;
    if (!registrationId) {
        throw err('INVALID_PARAMS', '缺少订单ID');
    }
    try {
        let registration = null;
        try {
            const regRes = await db.collection('activity_registrations').doc(registrationId).get();
            if (regRes.data && regRes.data.ownerId === openid) {
                registration = regRes.data;
            }
        }
        catch (e) {
            logger.warn('getRegistrationDetail.activity_registrations.fetch', { registrationId, code: e.errCode, msg: e.message });
        }
        if (!registration) {
            try {
                const orderRes = await db.collection('orders').doc(registrationId).get();
                if (orderRes.data) {
                    const order = orderRes.data;
                    if (order.ownerId === openid) {
                        const regQuery = await db.collection('activity_registrations')
                            .where({ activityId: order.activityId, ownerId: openid })
                            .limit(1).get();
                        const regData = (regQuery.data || []);
                        if (regData.length > 0) {
                            registration = regData[0];
                        }
                        else {
                            registration = {
                                _id: order._id,
                                activityId: order.activityId || '',
                                ownerId: openid,
                                pets: order.petsInfo || [],
                                phone: order.phone || '',
                                notes: order.notes || '',
                                participantCount: order.participantCount || 1,
                                petCount: order.petCount || 0,
                                totalAmount: order.totalPrice || order.basicPrice || 0,
                                originalAmount: order.originalAmount || order.totalPrice || 0,
                                couponId: order.couponId || '',
                                couponDiscount: order.couponDiscount || 0,
                                finalAmount: order.totalPrice || 0,
                                status: order.status || 'pending',
                                createdAt: order.createdAt,
                            };
                        }
                    }
                    else {
                        throw err('AUTH_REQUIRED', '无权查看此订单');
                    }
                }
            }
            catch (e) {
                logger.warn('getRegistrationDetail.orders.lookup', { registrationId, code: e.errCode, msg: e.message });
            }
        }
        if (!registration) {
            throw err('NOT_FOUND', '订单不存在');
        }
        let activityInfo = null;
        try {
            const activityRes = await db.collection('activities').doc(registration.activityId).get();
            if (activityRes.data) {
                const act = activityRes.data;
                activityInfo = {
                    title: act.title || '',
                    coverUrl: act.coverUrl || '',
                    startTime: act.startTime || '',
                    endTime: act.endTime || '',
                    location: act.location || '',
                    pricePerPerson: act.pricePerPerson || 0,
                    pricePerPet: act.pricePerPet || 0,
                };
            }
        }
        catch (e) {
            logger.warn('getRegistrationDetail: 获取活动信息失败', e.message);
        }
        return handleSuccess({
            registration,
            activityInfo,
        }, '获取成功');
    }
    catch (error) {
        logger.error('getRegistrationDetail', error);
        return handleError(error, '获取报名详情失败', ERROR_CODES.BUSINESS);
    }
}
exports.getRegistrationDetail = getRegistrationDetail;
// =====================================================================
// Handler 8: getRegistrationList - 报名列表
// =====================================================================
async function getRegistrationList(event, context, auth) {
    const { openid } = auth;
    if (!openid) {
        throw err('AUTH_REQUIRED', '未登录');
    }
    const { page = 1, pageSize = 20, activityId, status } = event;
    // M5 修复：pageSize 增加下限保护（0/负数/非数字回退默认），与其他 handler 口径一致
    const safePageSize = Math.min(Math.max(1, Number(pageSize) || 20), 20);
    const where = { ownerId: openid };
    if (activityId) {
        where.activityId = activityId;
    }
    // M5 修复：status==='active'（进行中的已报名活动）过滤提前到查询层，
    // 分页与 total 均基于过滤后的数据集，不再对"当前页"做内存过滤导致分页错乱
    if (status === 'active') {
        const myRegs = await fetchAllPaged('activity_registrations', { ownerId: openid, status: 'confirmed' }, 'createdAt', 1000);
        const myActivityIds = [...new Set(myRegs.map((r) => r.activityId).filter((id) => Boolean(id)))];
        if (myActivityIds.length === 0) {
            return handleSuccess({ list: [], total: 0, page, pageSize: safePageSize }, '获取成功');
        }
        const now = new Date();
        const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
        const bjTime = new Date(utc + (8 * 3600000));
        const nowStr = `${bjTime.getFullYear()}-${String(bjTime.getMonth() + 1).padStart(2, '0')}-${String(bjTime.getDate()).padStart(2, '0')} ${String(bjTime.getHours()).padStart(2, '0')}:${String(bjTime.getMinutes()).padStart(2, '0')}`;
        const activeIds = [];
        for (let i = 0; i < myActivityIds.length; i += 100) {
            const actRes = await db.collection('activities')
                .where({
                _id: _.in(myActivityIds.slice(i, i + 100)),
                status: _.nin(['ended', 'cancelled', 'deleted']),
            })
                .field({ _id: true, endTime: true })
                .get();
            (actRes.data || []).forEach((a) => {
                if (!a._id) {
                    return;
                }
                if (a.endTime && String(a.endTime) <= nowStr) {
                    return;
                }
                activeIds.push(a._id);
            });
        }
        if (activeIds.length === 0) {
            return handleSuccess({ list: [], total: 0, page, pageSize: safePageSize }, '获取成功');
        }
        where.activityId = _.in(activeIds);
        where.status = 'confirmed';
    }
    else if (status) {
        where.status = status;
    }
    const result = await paginate(db, 'activity_registrations', {
        page, pageSize: safePageSize, where, projection: REGISTRATION_LIST_FIELDS,
        orderBy: { field: 'createdAt', direction: 'desc' },
    });
    const activityIds = [...new Set(result.list.map((r) => r.activityId).filter((id) => Boolean(id)))];
    if (activityIds.length > 0) {
        const activitiesRes = await db.collection('activities')
            .where({ _id: _.in(activityIds) })
            .get();
        const activityMap = {};
        (activitiesRes.data || []).forEach((a) => { if (a._id) {
            activityMap[a._id] = a;
        } });
        // M5 修复：regMap 保留每个活动"最新"一条报名（列表已按 createdAt desc 排序，首条即最新），
        // 存量重复报名不再互相覆盖
        const regMap = {};
        result.list.forEach((r) => {
            if (r.activityId && !regMap[r.activityId]) {
                regMap[r.activityId] = r;
            }
        });
        const activities = activityIds
            .map((id) => activityMap[id])
            .filter((a) => Boolean(a))
            .map((a) => {
            const reg = regMap[a._id || ''];
            return {
                ...a,
                joined: true,
                _registrationId: reg ? (reg._id || '') : (a._id || ''),
                regStatus: reg ? reg.status : '',
                regCreatedAt: reg ? reg.createdAt : a.createdAt,
            };
        });
        // M5 修复：active 过滤已提前到查询层（见上方 where 构造），此处不再内存过滤、不再覆盖 result.total
        const invalidAvatarList = [];
        for (const activity of activities) {
            if (activity.organizer && activity.organizer.avatar) {
                const avatar = activity.organizer.avatar;
                if (!avatar.startsWith('cloud://') && !avatar.startsWith('https://')) {
                    activity.organizer.avatar = '';
                    if (activity.createdBy) {
                        invalidAvatarList.push(activity);
                    }
                }
            }
        }
        if (invalidAvatarList.length > 0) {
            const creatorOpenids = [...new Set(invalidAvatarList.map((a) => a.createdBy).filter((id) => Boolean(id)))];
            try {
                const adminRes = await db.collection('admins').where({ _id: _.in(creatorOpenids) }).field({ avatarUrl: true, nickName: true }).get();
                const adminMap = {};
                (adminRes.data || []).forEach((a) => { if (a._id) {
                    adminMap[a._id] = a;
                } });
                invalidAvatarList.forEach((activity) => {
                    if (!activity.createdBy || !activity.organizer) {
                        return;
                    }
                    const admin = adminMap[activity.createdBy];
                    if (admin && admin.avatarUrl && (admin.avatarUrl.startsWith('cloud://') || admin.avatarUrl.startsWith('https://'))) {
                        activity.organizer.avatar = admin.avatarUrl;
                        if (admin.nickName && activity.organizer.name === '宠团团') {
                            activity.organizer.name = admin.nickName;
                        }
                    }
                });
            }
            catch (e) {
                logger.warn('getRegistrationList.admins.fetch', { count: creatorOpenids.length, code: e.errCode, msg: e.message });
            }
        }
        result.list = activities;
    }
    else {
        result.list = [];
    }
    return handleSuccess(result, '获取成功');
}
exports.getRegistrationList = getRegistrationList;
// =====================================================================
// Handler 9: createActivityPaymentOrder - 创建活动支付订单
// =====================================================================
async function createActivityPaymentOrder(event, context, auth) {
    const { openid } = auth;
    if (!openid) {
        throw err('AUTH_REQUIRED', '未登录');
    }
    const { activityId, pets, phone, notes, friends, petIds, totalAmount, originalAmount, couponId, couponDiscount, orderId, participantCount } = event;
    if (!activityId) {
        throw err('INVALID_PARAMS', '缺少活动ID');
    }
    if (!pets || !Array.isArray(pets) || pets.length === 0) {
        throw err('INVALID_PARAMS', '请选择参与的宠物');
    }
    if (!phone) {
        throw err('INVALID_PARAMS', '请填写联系电话');
    }
    if (!orderId) {
        throw err('INVALID_PARAMS', '缺少订单ID');
    }
    try {
        const activityRes = await db.collection('activities').doc(activityId).get();
        const activity = activityRes.data;
        if (!activity) {
            throw err('NOT_FOUND', '活动不存在');
        }
        if (activity.maxParticipants && (activity.currentParticipants || 0) >= activity.maxParticipants) {
            throw err('BUSINESS_ERROR', '报名人数已满');
        }
        const existReg = await db.collection('activity_registrations')
            .where({ activityId, ownerId: openid, status: _.in(['confirmed', 'pending_payment']) })
            .count();
        if (existReg.total > 0) {
            throw err('BUSINESS_ERROR', '您已报名此活动');
        }
        const petsArray = pets;
        const friendsArray = Array.isArray(friends) ? friends : [];
        // M2 修复：participantCount 服务端规范化（≥1 的整数）
        const pCount = Math.max(1, Math.floor(Number(participantCount) || 1));
        const petCount = petsArray.length + friendsArray.length;
        // H3 修复：金额服务端重算，不信任前端 totalAmount
        const calculatedAmount = computeActivityAmount(activity, pCount, petCount);
        const coupon = await resolveCoupon(openid, couponId, calculatedAmount);
        const finalAmount = Math.max(0, Math.round((calculatedAmount - coupon.discount) * 100) / 100);
        if (finalAmount <= 0) {
            throw err('INVALID_PARAMS', '订单金额异常，请联系客服');
        }
        const now = db.serverDate();
        const petsInfo = petsArray.map((p) => ({
            name: p.petName || p.name || '',
            gender: p.petGender || p.gender || 'male',
            breed: p.petBreed || p.breed || '',
            petId: p.petId || '',
        }));
        // V3 升级：生成 ACT_ 前缀商户单号（与 paymentService 的 outTradeNo 路由约定一致，
        // paymentNotify 回调按前缀识别订单类型、按 outTradeNo 字段查 activity_registrations）
        const outTradeNo = `ACT_${Date.now()}_${_wxRandomString(6).toUpperCase()}`;
        const pendingRegistration = {
            _id: generateId('registration', openid),
            activityId,
            ownerId: openid,
            openid,
            orderId,
            outTradeNo,
            pets: petsInfo,
            petIds: petIds || [],
            phone: phone || '',
            notes: notes || '',
            friends: friendsArray,
            status: 'pending_payment',
            participantCount: pCount,
            petCount,
            totalAmount: calculatedAmount,
            originalAmount: calculatedAmount,
            couponId: coupon.couponId,
            couponDiscount: coupon.discount,
            finalAmount,
            createdAt: now,
            updatedAt: now,
        };
        const regResult = await db.collection('activity_registrations').add({ data: pendingRegistration });
        const orderDoc = {
            ownerId: openid,
            orderType: 'activity',
            orderId,
            outTradeNo,
            activityId,
            activityTitle: activity.title || '',
            activityCoverUrl: activity.coverUrl || '',
            activityStartTime: activity.startTime || '',
            activityEndTime: activity.endTime || '',
            activityLocation: activity.location || '',
            organizerId: activity.createdBy || '',
            petIds: petIds || [],
            petsInfo,
            startDate: activity.startTime || '',
            endDate: activity.endTime || '',
            duration: 1,
            pricePerDay: activity.price || 0,
            participantCount: pCount,
            petCount,
            basicPrice: calculatedAmount,
            totalPrice: finalAmount,
            originalAmount: calculatedAmount,
            couponId: coupon.couponId,
            couponDiscount: coupon.discount,
            phone: phone || '',
            notes: notes || '',
            status: 'pending_payment',
            paymentStatus: 'pending',
            createdAt: now,
            updatedAt: now,
        };
        await db.collection('orders').add({ data: orderDoc });
        const paymentParams = await _createPaymentParams(openid, orderId || '', outTradeNo, finalAmount, activity.title || '活动报名');
        return handleSuccess({
            orderId,
            outTradeNo,
            registrationId: regResult._id,
            paymentParams,
        }, '订单创建成功');
    }
    catch (error) {
        return handleError(error, '创建订单失败', ERROR_CODES.DATA);
    }
}
exports.createActivityPaymentOrder = createActivityPaymentOrder;
// =====================================================================
// Handler 10: confirmActivityPayment - 确认活动支付
// =====================================================================
async function confirmActivityPayment(event, context, auth) {
    const { openid } = auth;
    if (!openid) {
        throw err('AUTH_REQUIRED', '未登录');
    }
    const { orderId } = event;
    if (!orderId) {
        throw err('INVALID_PARAMS', '缺少订单ID');
    }
    // 事务前：查询订单（CloudBase 事务内不支持 where().get()/update()，必须先查 _id）
    const orderRes = await db.collection('orders').where({ orderId, ownerId: openid }).limit(1).get();
    const orderList = (orderRes.data || []);
    if (orderList.length === 0) {
        throw err('NOT_FOUND', '订单不存在');
    }
    const order = orderList[0];
    // V3 升级：幂等互斥——paymentNotify 回调可能已先行确认（status=confirmed + paymentStatus=paid），
    // 此时直接返回成功，避免重复递增活动名额
    if (order.paymentStatus === 'paid' || order.status === 'confirmed') {
        return handleSuccess({ orderId, alreadyConfirmed: true }, '支付成功');
    }
    if (order.status !== 'pending_payment') {
        throw err('BUSINESS_ERROR', '订单状态异常');
    }
    // H2 修复：向微信查单核实真实支付状态，杜绝 0 元"确认支付"
    // V3 升级：查单改用 V3 商户单号 outTradeNo（旧数据无 outTradeNo 时回退 orderId 兼容 V2 存量单）
    const wxQuery = await _queryWechatOrder(order.outTradeNo || orderId);
    if (!wxQuery.paid) {
        throw err('BUSINESS_ERROR', '支付未完成或支付状态未确认，请稍后重试');
    }
    const expectedFee = Math.round((order.totalPrice || order.basicPrice || 0) * 100);
    if (wxQuery.totalFee !== undefined && expectedFee > 0 && wxQuery.totalFee !== expectedFee) {
        logger.error('confirmActivityPayment.amountMismatch', { orderId, expectedFee, actualFee: wxQuery.totalFee });
        throw err('BUSINESS_ERROR', '支付金额与订单不一致，请联系客服');
    }
    // 事务前：查询需要更新的 activity_registrations _id 列表
    let registrationIds = [];
    try {
        const regRes = await db.collection('activity_registrations')
            .where({ orderId, ownerId: openid, status: 'pending_payment' })
            .field({ _id: true })
            .limit(10)
            .get();
        registrationIds = ((regRes && regRes.data) || []).map((r) => r._id);
    }
    catch (e) {
        // 查询失败不阻塞流程，但记录日志
        logger.warn('confirmActivityPayment.queryRegistrations.failed', {
            orderId, openid, msg: e?.message,
        });
    }
    const transaction = await db.startTransaction();
    try {
        const now = db.serverDate();
        // 1) 更新订单状态（V3 升级：落库微信交易号 transactionId）
        await transaction.collection('orders').doc(order._id || '').update({
            data: {
                status: 'confirmed',
                paymentStatus: 'paid',
                transactionId: wxQuery.transactionId || '',
                paidAt: now,
                updatedAt: now,
            },
        });
        // 2) 同步 activity_registrations 状态（事务内逐个 doc(id).update()）
        // 同时置 paymentStatus='paid'：与 paymentNotify 回调的幂等守卫（读报名单 paymentStatus==='paid' 直接返回）对齐，
        // 避免"前端主动确认 + 微信回调"两条路径对同一订单重复递增 currentParticipants。
        for (const regId of registrationIds) {
            await transaction.collection('activity_registrations').doc(regId).update({
                data: { status: 'confirmed', paymentStatus: 'paid', updatedAt: now },
            });
        }
        // 3) 活动名额递增
        // M2 修复：口径统一为"人数"（与 submitRegistration 免费路径一致），不再误用宠物数
        await transaction.collection('activities').doc(order.activityId || '').update({
            data: {
                currentParticipants: _.inc(order.participantCount || 1),
                updatedAt: now,
            },
        });
        await transaction.commit();
        // 活动佣金在活动结束时生成，不在支付时生成
        // 佣金由 autoUpdateActivityStatus 在活动时间到达 endTime 时触发
        return handleSuccess({ orderId }, '支付成功');
    }
    catch (error) {
        try {
            await transaction.rollback();
        }
        catch (_) { /* ignore rollback error */ }
        logger.error('confirmActivityPayment.transaction.failed', {
            orderId, openid, msg: error?.message,
            alert: '活动支付确认 DB 状态同步失败，需人工对账',
        });
        return handleError(error, '支付确认失败', ERROR_CODES.DATA);
    }
}
exports.confirmActivityPayment = confirmActivityPayment;
// =====================================================================
// Handler 11: getActivityRegistrations - 活动报名列表（合作伙伴）
// =====================================================================
async function getActivityRegistrations(event, context, auth) {
    const { openid } = auth;
    if (!openid) {
        throw err('AUTH_REQUIRED', '未登录');
    }
    const { activityId, page = 1, pageSize = 20 } = event;
    if (!activityId) {
        throw err('INVALID_PARAMS', '缺少活动ID');
    }
    const admin = await checkPartnerPermission(openid, 'activity');
    const isSuperAdmin = (admin.roles || []).includes('super_admin');
    // H5 修复：非超级管理员强制校验活动归属，防止横向越权查看他人活动报名
    if (!isSuperAdmin) {
        const actRes = await db.collection('activities').doc(activityId).get();
        const act = actRes.data;
        if (!act || act.createdBy !== openid) {
            throw err('PERMISSION_DENIED', '无权查看该活动的报名信息');
        }
    }
    const safePageSize = Math.min(Math.max(1, Number(pageSize) || 20), 100);
    const result = await paginate(db, 'activity_registrations', {
        page, pageSize: safePageSize,
        where: { activityId },
        orderBy: { field: 'createdAt', direction: 'desc' },
    });
    if (result.list && result.list.length > 0) {
        const openids = result.list.map((r) => r.ownerId).filter((id) => Boolean(id));
        if (openids.length > 0) {
            const usersRes = await db.collection('users').where({ _id: _.in(openids) }).get();
            const userMap = {};
            (usersRes.data || []).forEach((u) => { if (u._id) {
                userMap[u._id] = u;
            } });
            result.list = result.list.map((r) => {
                const user = userMap[r.ownerId || ''] || {};
                return {
                    ...r,
                    phone: maskPhone(r.phone),
                    userNickName: user.nickName || '',
                    userAvatar: user.avatarUrl || '',
                    displayName: user.nickName || '未知用户',
                };
            });
        }
        else {
            result.list = result.list.map((r) => ({
                ...r,
                phone: maskPhone(r.phone),
                userNickName: '',
                userAvatar: '',
                displayName: '未知用户',
            }));
        }
    }
    return handleSuccess(result, '获取成功');
}
exports.getActivityRegistrations = getActivityRegistrations;
// =====================================================================
// Handler 12: exportActivityRegistrations - 导出活动报名（CSV）
// =====================================================================
async function exportActivityRegistrations(event, context, auth) {
    const { openid } = auth;
    if (!openid) {
        throw err('AUTH_REQUIRED', '未登录');
    }
    const { activityId } = event;
    if (!activityId) {
        throw err('INVALID_PARAMS', '缺少活动ID');
    }
    const admin = await checkPartnerPermission(openid, 'activity');
    const isSuperAdmin = (admin.roles || []).includes('super_admin');
    const activityRes = await db.collection('activities').doc(activityId).get();
    const activity = activityRes.data;
    if (!activity) {
        throw err('NOT_FOUND', '活动不存在');
    }
    // H5 修复：非超级管理员强制校验活动归属，防止横向越权导出全平台报名数据
    if (!isSuperAdmin && activity.createdBy !== openid) {
        throw err('PERMISSION_DENIED', '无权导出该活动的报名信息');
    }
    // M3 修复：循环分页拉取全量报名，规避单次 get 上限静默截断（大活动导出不全）
    let registrations = await fetchAllPaged('activity_registrations', { activityId }, 'createdAt');
    if (registrations.length > 0) {
        const openids = [...new Set(registrations.map((r) => r.ownerId).filter((id) => Boolean(id)))];
        if (openids.length > 0) {
            // M3 修复：_.in 大数组分批查询（每批 100），规避服务端 in 数组上限
            const userMap = {};
            for (let i = 0; i < openids.length; i += 100) {
                const idBatch = openids.slice(i, i + 100);
                const usersRes = await db.collection('users').where({ _id: _.in(idBatch) }).field({ nickName: true }).get();
                (usersRes.data || []).forEach((u) => { if (u._id) {
                    userMap[u._id] = u;
                } });
            }
            registrations = registrations.map((r) => ({
                ...r,
                userNickName: (r.ownerId && userMap[r.ownerId]?.nickName) || '',
            }));
        }
    }
    const headers = ['序号', '宠物昵称', '报名时间', '用户昵称', '联系电话', '备注', '签到'];
    const rows = registrations.map((reg, index) => [
        index + 1,
        (reg.pets && reg.pets.map((p) => p.name).join(', ')) || '',
        reg.createdAt ? new Date(reg.createdAt).toLocaleString('zh-CN') : '',
        reg.userNickName || '',
        reg.phone || '',
        reg.notes || '',
        '',
    ]);
    // M3 修复：sanitizeCsvCell 防公式注入（= + - @ 开头的用户可控内容）
    const csvContent = [headers.join(','), ...rows.map((row) => row.map((cell) => {
            const str = sanitizeCsvCell(cell).replace(/"/g, '""');
            return `"${str}"`;
        }).join(','))].join('\n');
    const exportResult = {
        activityTitle: activity.title || '',
        totalCount: registrations.length,
        csvContent,
    };
    return handleSuccess(exportResult, '导出成功');
}
exports.exportActivityRegistrations = exportActivityRegistrations;
// =====================================================================
// Handler 13: getActivityOrders - 活动订单列表（合作伙伴）
// =====================================================================
async function getActivityOrders(event, context, auth) {
    const { openid } = auth;
    if (!openid) {
        throw err('AUTH_REQUIRED', '未登录');
    }
    const admin = await checkPartnerPermission(openid, 'activity');
    const isSuperAdmin = (admin.roles || []).includes('super_admin');
    const { status, page = 1, pageSize = 20 } = event;
    const safePageSize = Math.min(Math.max(1, Number(pageSize) || 20), 100);
    const where = { orderType: 'activity' };
    if (status) {
        where.status = status;
    }
    // H5 修复：非超级管理员仅能查看自己创建的活动订单，防止全平台订单泄露
    if (!isSuperAdmin) {
        where.organizerId = openid;
    }
    const result = await paginate(db, 'orders', {
        page, pageSize: safePageSize,
        where,
        orderBy: { field: 'createdAt', direction: 'desc' },
    });
    const list = (result.list || []);
    const enrichedList = list.map((order) => ({
        ...order,
        buyerNickName: order.ownerInfo?.nickName || '',
        productName: order.activityTitle || '',
        ownerInfo: order.ownerInfo ? { ...order.ownerInfo, phone: maskPhone(order.ownerInfo.phone) } : order.ownerInfo,
    }));
    return handleSuccess({ ...result, list: enrichedList }, '获取成功');
}
exports.getActivityOrders = getActivityOrders;
